    try {
        tokenValue = HiveDataset.extractTokenValueFromEntity("dbPrefix_myDB_dbPostfix", "dbPrefix_$LOGICAL_TABLE_dbPostfix", HiveDataset.LOGICAL_DB_TOKEN);
